-- This code has been fully generated by an AI.
--
-- Training values from the FIT session, laps, best efforts and weather.
-- Laps and efforts are derived from the raw file like stream and track and
-- are replaced on every re-derivation; weather is fetched from Open-Meteo
-- and kept across re-derivations.

ALTER TABLE activity ADD COLUMN training_effect REAL;
ALTER TABLE activity ADD COLUMN anaerobic_training_effect REAL;
ALTER TABLE activity ADD COLUMN training_load REAL;
ALTER TABLE activity ADD COLUMN normalized_power INTEGER;
ALTER TABLE activity ADD COLUMN training_stress_score REAL;
ALTER TABLE activity ADD COLUMN intensity_factor REAL;
ALTER TABLE activity ADD COLUMN threshold_power INTEGER;
ALTER TABLE activity ADD COLUMN rpe REAL;
ALTER TABLE activity ADD COLUMN feel INTEGER;

-- Laps from the device, or automatic distance splits (auto = 1) for
-- activities recorded as a single lap. Times are seconds since the start.
CREATE TABLE activity_lap (
    activity_id    INTEGER NOT NULL REFERENCES activity (id) ON DELETE CASCADE,
    idx            INTEGER NOT NULL,
    auto           INTEGER NOT NULL,
    start_s        REAL    NOT NULL,
    end_s          REAL    NOT NULL,
    timer_s        REAL    NOT NULL,
    distance_m     REAL    NOT NULL,
    ascent_m       INTEGER,
    descent_m      INTEGER,
    avg_speed_mps  REAL,
    max_speed_mps  REAL,
    avg_heart_rate INTEGER,
    max_heart_rate INTEGER,
    avg_power      INTEGER,
    avg_cadence    INTEGER,
    PRIMARY KEY (activity_id, idx)
);

-- Best efforts of an activity. kind 'distance': key = meters, value =
-- seconds (lower is better); 'power': key = seconds, value = watts;
-- 'climb': key = 0, value = net gain in m, extra = distance in m.
-- grp is the record group ('bike', 'run', 'hike') the effort competes in.
CREATE TABLE activity_effort (
    activity_id INTEGER NOT NULL REFERENCES activity (id) ON DELETE CASCADE,
    grp         TEXT    NOT NULL,
    kind        TEXT    NOT NULL,
    key         INTEGER NOT NULL,
    value       REAL    NOT NULL,
    start_s     REAL    NOT NULL,
    end_s       REAL    NOT NULL,
    extra       REAL,
    PRIMARY KEY (activity_id, kind, key)
);

CREATE INDEX activity_effort_rank ON activity_effort (grp, kind, key, value);

-- Weather at the start point during the activity (Open-Meteo). status is
-- 'ok', 'none' (no GPS) or 'error' (retried later).
CREATE TABLE activity_weather (
    activity_id  INTEGER PRIMARY KEY REFERENCES activity (id) ON DELETE CASCADE,
    status       TEXT    NOT NULL,
    fetched_at   INTEGER NOT NULL,
    error        TEXT,
    temp_min_c   REAL,
    temp_max_c   REAL,
    apparent_c   REAL,
    wind_kmh     REAL,
    wind_dir_deg REAL,
    gust_kmh     REAL,
    precip_mm    REAL,
    weather_code INTEGER
);
